#!/usr/bin/env bash
# recipes/crate-os-str-bytes--6-6-1/build.sh -- stage the os_str_bytes 6.6.1 crate as
# an entry of the cargo directory source share/cargo/crates/ (docs/rust-crates.md).
# Generated by tools/make_crate_packages.py.
set -euo pipefail
dest="${CVC_INSTALL_DIR}/share/cargo/crates/os_str_bytes-6.6.1"
